import { useEffect, useState } from 'react';

export const useReset = (restart: number, delay: number = 100) => {
	const [instanceKey, setInstanceKey] = useState(0);

	useEffect(() => {
		const timer = setTimeout(() => {
			setInstanceKey((prev) => prev + restart);
		}, delay);
		return () => clearTimeout(timer);
	}, [restart, delay]);

	return instanceKey;
};
