import { useRef, useState, useEffect } from 'react';

import { BezierInterpolation } from './BezierInterpolation';
import { Delaunay, NVector3 } from 'lib/NJSCore';

import { DelaunayTriangulation } from './DelaunayTriangulation';

const CanvasDynamics = ({mapRef}) => {
	const canvasRef = useRef<HTMLCanvasElement>(null);
	const canvasRenderRef = useRef<CanvasRenderer>(null);

	const [isDragging, setIsDragging] = useState(false);
	const [sizeContainer, setSizeContainer] = useState([0,0]);
	const [startPos, setStartPos] = useState<{ x: number; y: number } | null>(null);

	const [bezierInterpolation] = useState(() => new BezierInterpolation(100));

	// const canvasRenderer = new CanvasRenderer();

	// useEffect(() => {
	// 	const canvas = canvasRef.current;
	// 	if (!canvas) return;

	// 	const ctx = canvas.getContext('2d');
	// 	if (!ctx) return;

	// 	ctx.fillStyle = 'white';
	// 	ctx.fillRect(0, 0, canvas.width, canvas.height);

	// 	bezierInterpolation.render(ctx);
	// }, [bezierInterpolation]);

	const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
		setIsDragging(true);
		const rect = canvasRef.current?.getBoundingClientRect();
		if (rect) {
			setStartPos({ x: e.clientX - rect.left, y: e.clientY - rect.top });

			const x = e.clientX - rect.left;
			const y = e.clientY - rect.top;

			bezierInterpolation.mouseDown(x, y);

			canvasRenderRef.current.mouseDown(x, y);
		}

	};

	const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
		if (!isDragging || !startPos) return;

		const canvas = canvasRef.current;
		const ctx = canvas?.getContext('2d');
		const rect = canvas?.getBoundingClientRect();

		if (ctx && rect) {
			//     console.log('dragging')
			const x = e.clientX - rect.left;
			const y = e.clientY - rect.top;

			//   ctx.strokeStyle = 'black';
			//   ctx.lineWidth = 2;
			//   ctx.beginPath();
			//   ctx.moveTo(startPos.x, startPos.y);
			//   ctx.lineTo(x, y);
			//   ctx.stroke();

			// console.log('ren')
			//   setStartPos({ x, y });

			bezierInterpolation.mouseDrag(x, y);
			bezierInterpolation.render(ctx);


			canvasRenderRef.current.render();
			//   console.log(bezierInterpolation.getProjection());
		}
	};

	const handleMouseUp = () => {
		setIsDragging(false);
		setStartPos(null);
		bezierInterpolation.mouseUp(0, 0);
	};

	useEffect(()=>{
		if (!mapRef.current) return null;

		const container = mapRef.current.getContainer();
		const width = container.clientWidth;
		const height = container.clientHeight;

		setSizeContainer([width, height]);


		const canvas = canvasRef.current;
		if (!canvas) return;

		const ctx = canvas.getContext('2d');
		if (!ctx) return;

		canvasRenderRef.current = new CanvasRenderer() 
		canvasRenderRef.current.toScreen = (lon: number, lat: number) => {
			const p = mapRef.current.project([lon, lat]);
			return [p.x, p.y];
		};
		canvasRenderRef.current.toMap = (x: number, y: number) => {
			const p = mapRef.current.unproject({x, y});
			return [p.lng, p.lat];
		};
	// public toMap = (x: number, y: number) => {
	//     const p = this.map.unproject({ x, y } as any);
	//     return [p.lng, p.lat];
	//   };
	//   public toScreen = (lon: number, lat: number) => {
	//     const p = this.map.project([lon, lat]);
	//     return [p.x, p.y];
	//   };
		canvasRenderRef.current.init(ctx);

	},[mapRef])

	return (
		<canvas
			ref={canvasRef}
			width={sizeContainer[0]}
			height={sizeContainer[1]}
			onMouseDown={handleMouseDown}
			onMouseMove={handleMouseMove}
			onMouseUp={handleMouseUp}
			onMouseLeave={handleMouseUp}
			style={{
				cursor: 'crosshair',
				background:'rgba(0,0,0,0.25)'
			}}
		/>
	);
};
export default CanvasDynamics;


