class EMPCanvasRenderer {
	public ctx: CanvasRenderingContext2D;
	private animationId: number | null = null;
	private startTime: number = 0;
	private isAnimating: boolean = false;
	
	private empCenter: { x: number; y: number } = { x: 100, y: 100 };
	private maxRadius: number = 800;
	private empDuration: number = 4000; // 4초
	private shockwaves: Array<{
		radius: number;
		opacity: number;
		speed: number;
		delay: number;
		thickness: number;
	}> = [];
	constructor() {
		this.setupShockwaves();
	}
	public init(ctx: CanvasRenderingContext2D) {
		this.ctx = ctx;
		this.empCenter = {
			x: ctx.canvas.width * 0.5,
			y: ctx.canvas.height * 0.5
		};
		this.maxRadius = Math.max(ctx.canvas.width, ctx.canvas.height) * 1.2;
		console.log('EMP Canvas Renderer initialized');
	}
	private setupShockwaves() {
		this.shockwaves = [
			{ radius: 10, opacity: 1.0, speed: 400, delay: 10, thickness: 2 },
			{ radius: 10, opacity: 0.7, speed: 320, delay: 150, thickness: 4 },
			{ radius: 10, opacity: 0.5, speed: 280, delay: 300, thickness: 6 },
			{ radius: 10, opacity: 0.3, speed: 240, delay: 450, thickness: 8 }
		];
	}
	public startEMPEffect(centerX?: number, centerY?: number) {
		if (!this.ctx) return;

		if (centerX !== undefined && centerY !== undefined) {
			this.empCenter = { x: centerX, y: centerY };
		}

		this.startTime = performance.now();
		this.isAnimating = true;
		// this.setupShockwaves();
		this.render();
	}
	public stopEMPEffect() {
		this.isAnimating = false;
		if (this.animationId) {
			cancelAnimationFrame(this.animationId);
			this.animationId = null;
		}
		this.clearCanvas();
	}
	private clearCanvas() {
		if (!this.ctx) return;
		this.ctx.clearRect(0, 0, this.ctx.canvas.width, this.ctx.canvas.height);
	}
	public render() {
		if (!this.ctx || !this.isAnimating) return;

		const currentTime = performance.now();
		const elapsed = currentTime - this.startTime;
		
		if (elapsed > this.empDuration) {
			this.stopEMPEffect();
			return;
		}

		this.clearCanvas();

		// console.log('rendering...', elapsed)

		this.renderInitialFlash(elapsed);
		// this.renderShockwaves(elapsed);
		this.renderEnergyCore(elapsed);
		// this.renderElectricField(elapsed);
		// this.renderDistortionField(elapsed);

		this.animationId = requestAnimationFrame(() => this.render());
	}
	private renderInitialFlash(elapsed: number) {
		if (elapsed > 400) return;
		this.maxRadius = Math.max(this.ctx.canvas.width, this.ctx.canvas.height) * 1.2;

		const flashProgress = elapsed / 400;
		const intensity = Math.pow(1 - flashProgress, 3) * 10.4;
		

		console.log(this.maxRadius)

		const gradient = this.ctx.createRadialGradient(
			this.empCenter.x, this.empCenter.y, 0,
			this.empCenter.x, this.empCenter.y, this.maxRadius * 0.8
		);
		gradient.addColorStop(0, `rgba(200, 230, 255, ${intensity})`);
		gradient.addColorStop(0.6, `rgba(120, 180, 255, ${intensity * 0.3})`);
		gradient.addColorStop(1, `rgba(60, 140, 255, 0)`);
		
		this.ctx.fillStyle = gradient;
		this.ctx.fillRect(0, 0, this.ctx.canvas.width, this.ctx.canvas.height);
	}
	private renderShockwaves(elapsed: number) {
		this.shockwaves.forEach((wave, index) => {
			const waveAge = elapsed - wave.delay;
			if (waveAge < 0) return;

			wave.radius = (waveAge / 1000) * wave.speed;
			
			if (wave.radius > this.maxRadius) return;

			const fadeProgress = Math.min(wave.radius / this.maxRadius, 1);
			const easedFade = 1 - Math.pow(fadeProgress, 2);
			const currentOpacity = wave.opacity * easedFade;

			this.ctx.beginPath();
			this.ctx.arc(this.empCenter.x, this.empCenter.y, wave.radius, 0, Math.PI * 2);
			
			const gradient = this.ctx.createRadialGradient(
				this.empCenter.x, this.empCenter.y, wave.radius - wave.thickness,
				this.empCenter.x, this.empCenter.y, wave.radius + wave.thickness
			);
			gradient.addColorStop(0, `rgba(100, 200, 255, 0)`);
			gradient.addColorStop(0.3, `rgba(150, 220, 255, ${currentOpacity * 0.8})`);
			gradient.addColorStop(0.7, `rgba(200, 240, 255, ${currentOpacity})`);
			gradient.addColorStop(1, `rgba(100, 200, 255, 0)`);

			this.ctx.strokeStyle = gradient;
			this.ctx.lineWidth = wave.thickness * 2;
			this.ctx.stroke();

			this.ctx.beginPath();
			this.ctx.arc(this.empCenter.x, this.empCenter.y, wave.radius, 0, Math.PI * 2);
			this.ctx.strokeStyle = `rgba(255, 255, 255, ${currentOpacity * 0.6})`;
			this.ctx.lineWidth = Math.max(1, wave.thickness * 0.5);
			this.ctx.stroke();

			if (index === 0) {
				this.ctx.beginPath();
				this.ctx.arc(this.empCenter.x, this.empCenter.y, wave.radius, 0, Math.PI * 2);
				const glowGradient = this.ctx.createRadialGradient(
					this.empCenter.x, this.empCenter.y, wave.radius - 15,
					this.empCenter.x, this.empCenter.y, wave.radius + 15
				);
				glowGradient.addColorStop(0, `rgba(180, 220, 255, 0)`);
				glowGradient.addColorStop(0.5, `rgba(180, 220, 255, ${currentOpacity * 0.3})`);
				glowGradient.addColorStop(1, `rgba(180, 220, 255, 0)`);
				
				this.ctx.strokeStyle = glowGradient;
				this.ctx.lineWidth = 20;
				this.ctx.stroke();
			}
		});
	}
	private renderEnergyCore(elapsed: number) {
		const coreSize = Math.min(elapsed / 15, 60);
		const pulseIntensity = 1 + Math.sin(elapsed * 0.015) * 0.3;
		const coreRadius = coreSize * pulseIntensity;
		
		const layers = [
			{ radius: coreRadius * 1.0, color: [255, 255, 255], opacity: 0.9 },
			{ radius: coreRadius * 0.7, color: [200, 230, 255], opacity: 0.7 },
			{ radius: coreRadius * 0.4, color: [150, 200, 255], opacity: 0.5 },
			{ radius: coreRadius * 0.2, color: [255, 255, 255], opacity: 1.0 }
		];

		layers.forEach(layer => {
			const fadeOut = Math.max(0, 1 - elapsed / this.empDuration);
			const currentOpacity = layer.opacity * fadeOut;
			
			const gradient = this.ctx.createRadialGradient(
				this.empCenter.x, this.empCenter.y, 0,
				this.empCenter.x, this.empCenter.y, layer.radius
			);
			gradient.addColorStop(0, `rgba(${layer.color.join(',')}, ${currentOpacity})`);
			gradient.addColorStop(0.8, `rgba(${layer.color.join(',')}, ${currentOpacity * 0.3})`);
			gradient.addColorStop(1, `rgba(${layer.color.join(',')}, 0)`);
			
			this.ctx.beginPath();
			this.ctx.arc(this.empCenter.x, this.empCenter.y, layer.radius, 0, Math.PI * 2);
			this.ctx.fillStyle = gradient;
			this.ctx.fill();
		});
	}
	private renderElectricField(elapsed: number) {
		if (elapsed < 200 || elapsed > 2500) return;
		
		const fieldIntensity = Math.sin((elapsed - 200) / 2300 * Math.PI) * 0.6;
		const particleCount = 30;
		const baseRadius = 80;
		
		for (let i = 0; i < particleCount; i++) {
			const angle = (i / particleCount) * Math.PI * 2;
			const radiusVariation = Math.sin(elapsed * 0.008 + i * 0.5) * 20;
			const currentRadius = baseRadius + radiusVariation + (elapsed - 200) * 0.05;
			
			const x = this.empCenter.x + Math.cos(angle) * currentRadius;
			const y = this.empCenter.y + Math.sin(angle) * currentRadius;
			
			const particleSize = 1 + Math.random() * 2;
			const opacity = fieldIntensity * (0.5 + Math.random() * 0.5);
			
			const glowGradient = this.ctx.createRadialGradient(x, y, 0, x, y, particleSize * 3);
			glowGradient.addColorStop(0, `rgba(180, 220, 255, ${opacity})`);
			glowGradient.addColorStop(0.5, `rgba(120, 180, 255, ${opacity * 0.5})`);
			glowGradient.addColorStop(1, `rgba(120, 180, 255, 0)`);
			
			this.ctx.beginPath();
			this.ctx.arc(x, y, particleSize * 3, 0, Math.PI * 2);
			this.ctx.fillStyle = glowGradient;
			this.ctx.fill();
			
			// 중심 입자
			this.ctx.beginPath();
			this.ctx.arc(x, y, particleSize, 0, Math.PI * 2);
			this.ctx.fillStyle = `rgba(255, 255, 255, ${opacity})`;
			this.ctx.fill();
		}
	}

	private renderDistortionField(elapsed: number) {
		if (elapsed < 800) return;
		
		const distortionProgress = ((elapsed - 800) / (this.empDuration - 800)) + 10;
		const intensity = Math.sin(distortionProgress * Math.PI) * 0.55;
		
		// console.log('renderDistortionField', elapsed, distortionProgress, intensity)
		const interferenceCount = 8;
		for (let i = 0; i < interferenceCount; i++) {
			const progress = i / interferenceCount;
			const y = this.ctx.canvas.height * progress;
			const offset = Math.sin(elapsed * 0.01 + i * 1.5) * 3;
			const opacity = intensity * (0.3 + Math.random() * 0.2);
			
			this.ctx.fillStyle = `rgba(150, 200, 255, ${opacity})`;
			this.ctx.fillRect(offset, y, this.ctx.canvas.width - offset * 2, 1);
		}

		const noiseCount = Math.floor(intensity * 20);
		for (let i = 0; i < noiseCount; i++) {
			const x = Math.random() * this.ctx.canvas.width;
			const y = Math.random() * this.ctx.canvas.height;
			const size = Math.random() * 1.5 + 0.5;
			const opacity = Math.random() * intensity * 0.5;
			
			this.ctx.fillStyle = `rgba(200, 230, 255, ${opacity})`;
			this.ctx.fillRect(x, y, size, size);
		}
	}

	public resize(width: number, height: number) {
		if (!this.ctx) return;
		
		this.ctx.canvas.width = width;
		this.ctx.canvas.height = height;
		this.empCenter = {
			x: width * 0.5,
			y: height * 0.5
		};
		this.maxRadius = Math.max(width, height) * 1.2;
	}

	public triggerEMPAt(x: number, y: number) {
		this.startEMPEffect(x, y);
	}

	public startContinuousPulse(interval: number = 3000) {
		this.startEMPEffect();
		
		setTimeout(() => {
			if (this.isAnimating) {
				this.startContinuousPulse(interval);
			}
		}, interval);
	}
}

